@* ===== SECURITY SECTION ===== *@
@{
    void SecuritySection()
    {
        <section class="settings-section">
            <h2>Security</h2>

            <div class="expandable-panel">
                <button class="panel-header" @onclick="TogglePasswordPanel">
                    <span>Change Password</span>
                    <span class="expand-icon">@(showPasswordPanel ? "▼" : "▶")</span>
                </button>
                @if (showPasswordPanel)
                {
                    <div class="panel-body">
                        <div class="form-group">
                            <label for="currentPassword">Current Password</label>
                            <input id="currentPassword" type="password" @bind="currentPassword" />
                        </div>
                        <div class="form-group">
                            <label for="newPassword">New Password</label>
                            <input id="newPassword" type="password" @bind="newPassword" />
                        </div>
                        <div class="form-group">
                            <label for="confirmPassword">Confirm Password</label>
                            <input id="confirmPassword" type="password" @bind="confirmPassword" />
                        </div>
                        <button class="btn-primary" @onclick="UpdatePassword">Update Password</button>
                    </div>
                }
            </div>

            <div class="two-factor-section">
                <h3>Two-Factor Authentication</h3>
                <div class="status-row">
                    <label class="toggle-label">
                        <input type="checkbox" checked="@twoFactorEnabled" disabled />
                        <span class="toggle-switch"></span>
                        Two-Factor Authentication
                    </label>
                    <span class="status-indicator @(twoFactorEnabled ? "status-enabled" : "status-disabled")">
                        @(twoFactorEnabled ? "Enabled" : "Disabled")
                    </span>
                </div>
                @if (lastPasswordChange.HasValue)
                {
                    <p class="info-text">Last password change: @lastPasswordChange.Value.ToString("MMMM dd, yyyy")</p>
                }
            </div>

            <div class="sessions-section">
                <h3>Active Sessions</h3>
                <table class="sessions-table">
                    <thead>
                        <tr>
                            <th>Device</th>
                            <th>Location</th>
                            <th>Last Active</th>
                            <th>Action</th>
                        </tr>
                    </thead>
                    <tbody>
                        @if (activeSessions != null)
                        {
                            @foreach (var session in activeSessions)
                            {
                                <tr>
                                    <td>@session.Device</td>
                                    <td>@session.Location</td>
                                    <td>@session.LastActive.ToString("g")</td>
                                    <td>
                                        @if (session != activeSessions.FirstOrDefault())
                                        {
                                            <button class="btn-danger btn-small" @onclick="() => ConfirmRevokeSession(session.Id)">
                                                Revoke
                                            </button>
                                        }
                                        else
                                        {
                                            <span class="current-badge">Current</span>
                                        }
                                    </td>
                                </tr>
                            }
                        }
                    </tbody>
                </table>
            </div>

            @if (showRevokeConfirmation)
            {
                <div class="modal-overlay" @onclick="CancelRevoke">
                    <div class="modal-dialog" @onclick:stopPropagation="true">
                        <h3>Confirm Session Revocation</h3>
                        <p>Are you sure you want to revoke this session? The user will be logged out on that device.</p>
                        <div class="button-group">
                            <button class="btn-danger" @onclick="RevokeSession">Revoke Session</button>
                            <button class="btn-secondary" @onclick="CancelRevoke">Cancel</button>
                        </div>
                    </div>
                </div>
            }
        </section>
    }
}

@* ===== APPEARANCE SECTION ===== *@
@{
    void AppearanceSection()
    {
        <section class="settings-section">
            <h2>Appearance</h2>

            <div class="form-group">
                <label>Theme</label>
                <div class="radio-group">
                    <label class="radio-label">
                        <input type="radio" name="theme" value="Light"
                               checked="@(appearanceTheme == "Light")"
                               @onchange='() => appearanceTheme = "Light"' />
                        Light
