                <div class="button-group">
                    <button class="btn-primary" @onclick="SaveProfile">Save Changes</button>
                    <button class="btn-secondary" @onclick="DiscardProfileChanges">Discard Changes</button>
                </div>
            </section>
        }
        else if (activeSection == "Notifications")
        {
            <section class="settings-section">
                <h2>Notifications</h2>

                <div class="toggle-group">
                    <label class="toggle-label">
                        <input type="checkbox" @bind="notifEmail" />
                        <span class="toggle-switch"></span>
                        Email Notifications
                    </label>
                </div>

                <div class="toggle-group">
                    <label class="toggle-label">
                        <input type="checkbox" @bind="notifPush" />
                        <span class="toggle-switch"></span>
                        Push Notifications
                    </label>
                </div>

                <div class="toggle-group">
                    <label class="toggle-label">
                        <input type="checkbox" @bind="notifWeeklyDigest" />
                        <span class="toggle-switch"></span>
                        Weekly Digest
                    </label>
                </div>

                <h3>Muted Channels</h3>
                <div class="channels-list">
                    @if (allChannels != null)
                    {
                        @foreach (var channel in allChannels)
                        {
                            var ch = channel;
                            <label class="channel-item">
                                <input type="checkbox"
                                       checked="@mutedChannels.Contains(ch)"
                                       @onchange="(e) => ToggleMuteChannel(ch, (bool)(e.Value ?? false))" />
                                @ch
                            </label>
                        }
                    }
                </div>

                <div class="button-group">
                    <button class="btn-primary" @onclick="SaveNotifications">Save Preferences</button>
                </div>
            </section>
        }
        else if (activeSection == "Security")
        {
            <section class="settings-section">
                <h2>Security</h2>

                <div class="expandable-panel">
                    <button class="panel-header" @onclick="TogglePasswordPanel">
                        <span>Change Password</span>
                        <span class="expand-icon">@(showPasswordPanel ? "▼" : "▶")</span>
                    </button>
                    @if (showPasswordPanel)
                    {
                        <div class="panel-body">
                            <div class="form-group">
                                <label for="currentPassword">Current Password</label>
                                <input id="currentPassword" type="password" @bind="currentPassword" />
                            </div>
                            <div class="form-group">
                                <label for="newPassword">New Password</label>
                                <input id="newPassword" type="password" @bind="newPassword" />
                            </div>
                            <div class="form-group">
                                <label for="confirmPassword">Confirm Password</label>
                                <input id="confirmPassword" type="password" @bind="confirmPassword" />
                            </div>
                            <button class="btn-primary" @onclick="UpdatePassword">Update Password</button>
                        </div>
                    }
                </div>

                <div class="two-factor-section">
                    <h3>Two-Factor Authentication</h3>
                    <div class="status-row">
                        <label class="toggle-label">
                            <input type="checkbox" checked="@twoFactorEnabled" disabled />
                            <span class="toggle-switch"></span>
                            Two-Factor Authentication
                        </label>
                        <span class="status-indicator @(twoFactorEnabled ? "status-enabled" : "status-disabled")">
                            @(twoFactorEnabled ? "Enabled" : "Disabled")
                        </span>
                    </div>
                    @if (lastPasswordChange.HasValue)
                    {
                        <p class="info-text">Last password change: @lastPasswordChange.Value.ToString("MMMM dd, yyyy")</p>
                    }
                </div>

                <div class="sessions-section">
                    <h3>Active Sessions</h3>
                    <table class="sessions-table">
                        <thead>
                            <tr>
                                <th>Device</th>
                                <th>Location</th>
                                <th>Last Active</th>
                                <th>Action</th>
                            </tr>
                        </thead>
                        <tbody>
                            @if (activeSessions != null)
                            {
                                @foreach (var session in activeSessions)
                                {
                                    <tr>
                                        <td>@session.Device</td>
                                        <td>@session.Location</td>
                                        <td>@session.LastActive.ToString("g")</td>
                                        <td>
                                            @if (session != activeSessions.FirstOrDefault())
                                            {
                                                <button class="btn-danger btn-small" @onclick="() => ConfirmRevokeSession(session.Id)">
                                                    Revoke
                                                </button>
                                            }
                                            else
                                            {
                                                <span class="current-badge">Current</span>
                                            }
                                        </td>
                                    </tr>
                                }
                            }
                        </tbody>
                    </table>
                </div>

                @if (showRevokeConfirmation)
                {
                    <div class="modal-overlay" @onclick="CancelRevoke">
                        <div class="modal-dialog" @onclick:stopPropagation="true">
                            <h3>Confirm Session Revocation</h3>
                            <p>Are you sure you want to revoke this session? The user will be logged out on that device.</p>
                            <div class="button-group">
                                <button class="btn-danger" @onclick="RevokeSession">Revoke Session</button>
                                <button class="btn-secondary" @onclick="CancelRevoke">Cancel</button>
                            </div>
                        </div>
                    </div>
                }
            </section>
        }
        else if (activeSection == "Appearance")
        {
            <section class="settings-section">
                <h2>Appearance</h2>

                <div class="form-group">
                    <label>Theme</label>
                    <div class="radio-group">
                        <label class="radio-label">
                            <input type="radio" name="theme" value="Light"
                                   checked="@(appearanceTheme == "Light")"
                                   @onchange='() => appearanceTheme = "Light"' />
                            Light
                        </label>
                        <label class="radio-label">
                            <input type="radio" name="theme" value="Dark"
                                   checked="@(appearanceTheme == "Dark")"
                                   @onchange='() => appearanceTheme = "Dark"' />
                            Dark
                        </label>
                        <label class="radio-label">
                            <input type="radio" name="theme" value="System"
                                   checked="@(appearanceTheme == "System")"
                                   @onchange='() => appearanceTheme = "System"' />
                            System
                        </label>
                    </div>
                </div>

                <div class="form-group">
                    <label>Font Size</label>
                    <div class="radio-group">
                        <label class="radio-label">
                            <input type="radio" name="fontSize" value="Small"
                                   checked="@(appearanceFontSize == "Small")"
                                   @onchange='() => appearanceFontSize = "Small"' />
                            Small
                        </label>
                        <label class="radio-label">
                            <input type="radio" name="fontSize" value="Medium"
                                   checked="@(appearanceFontSize == "Medium")"
                                   @onchange='() => appearanceFontSize = "Medium"' />
                            Medium
                        </label>
                        <label class="radio-label">
                            <input type="radio" name="fontSize" value="Large"
                                   checked="@(appearanceFontSize == "Large")"
                                   @onchange='() => appearanceFontSize = "Large"' />
                            Large
                        </label>
                    </div>
                </div>

                <div class="form-group">
                    <label for="language">Language</label>
                    <select id="language" @bind="appearanceLanguage">
                        <option value="en">English</option>
                        <option value="es">Spanish</option>
                        <option value="fr">French</option>
                        <option value="de">German</option>
                        <option value="ja">Japanese</option>
                        <option value="zh">Chinese</option>
                        <option value="pt">Portuguese</option>
                    </select>
                </div>

                <div class="toggle-group">
                    <label class="toggle-label">
                        <input type="checkbox" @bind="appearanceCompactMode" />
                        <span class="toggle-switch"></span>
                        Compact Mode
                    </label>
                </div>

                <div class="live-preview" style="@GetPreviewStyle()">
                    <h4>Live Preview</h4>
                    <p>This is how your content will look with the selected settings.</p>
                    <p>Theme: @appearanceTheme | Font: @appearanceFontSize | Compact: @(appearanceCompactMode ? "Yes" : "No")</p>
                </div>

                <div class="button-group">
                    <button class="btn-primary" @onclick="SaveAppearance">Save</button>
                </div>
            </section>
        }

        @if (!string.IsNullOrEmpty(toastMessage))
        {
            <div class="toast @toastType">
                @toastMessage
                <button class="toast-close" @onclick="DismissToast">✕</button>
            </div>
        }
    </main>
</div>

@code {
    private string activeSection = "Profile";
    private bool isLoading = true;
    private string? toastMessage;
    private string toastType = "success";

    // Profile state
    private string profileDisplayName = "";
    private string profileEmail = "";
    private string profileAvatarUrl = "";
    private string profileBio = "";
    private UserProfile? savedProfile;

    // Notifications state
    private bool notifEmail;
    private bool notifPush;
    private bool notifWeeklyDigest;
    private List<string> mutedChannels = new();
    private List<string> allChannels = new() { "general", "announcements", "random", "engineering", "design", "marketing" };

    // Security state
    private bool showPasswordPanel;
    private string currentPassword = "";
    private string newPassword = "";
    private string confirmPassword = "";
    private bool twoFactorEnabled;
    private DateTime? lastPasswordChange;
    private List<ActiveSession>? activeSessions;
    private bool showRevokeConfirmation;
    private string? sessionToRevoke;

    // Appearance state
    private string appearanceTheme = "System";
    private string appearanceFontSize = "Medium";
    private string appearanceLanguage = "en";
    private bool appearanceCompactMode;

    protected override async Task OnInitializedAsync()
    {
        await LoadSectionData();
    }

    private async Task SetSection(string section)
    {
        activeSection = section;
        isLoading = true;
        await LoadSectionData();
    }

    private async Task LoadSectionData()
    {
        try
        {
            switch (activeSection)
            {
                case "Profile":
                    var profile = await SettingsService.GetProfileAsync();
                    savedProfile = profile;
                    profileDisplayName = profile.DisplayName;
                    profileEmail = profile.Email;
                    profileAvatarUrl = profile.AvatarUrl;
                    profileBio = profile.Bio;
                    break;

                case "Notifications":
                    var notifs = await SettingsService.GetNotificationPrefsAsync();
                    notifEmail = notifs.EmailNotifications;
                    notifPush = notifs.PushNotifications;
                    notifWeeklyDigest = notifs.WeeklyDigest;
                    mutedChannels = new List<string>(notifs.MutedChannels);
                    break;

                case "Security":
                    var security = await SettingsService.GetSecuritySettingsAsync();
                    twoFactorEnabled = security.TwoFactorEnabled;
                    lastPasswordChange = security.LastPasswordChange;
                    activeSessions = security.Sessions;
                    break;

                case "Appearance":
                    var appearance = await SettingsService.GetAppearanceAsync();
                    appearanceTheme = appearance.Theme;
                    appearanceFontSize = appearance.FontSize;
                    appearanceLanguage = appearance.Language;
                    appearanceCompactMode = appearance.CompactMode;
                    break;
            }
        }
        catch (Exception ex)
        {
            ShowToast($"Error loading settings: {ex.Message}", "error");
        }
        finally
        {
            isLoading = false;
        }
    }

    // Profile actions
    private async Task SaveProfile()
    {
        var profile = new UserProfile(profileDisplayName, profileEmail, profileAvatarUrl, profileBio);
        await SettingsService.SaveProfileAsync(profile);
        savedProfile = profile;
        ShowToast("Profile saved successfully!", "success");
    }

    private void DiscardProfileChanges()
    {
        if (savedProfile != null)
        {
            profileDisplayName = savedProfile.DisplayName;
            profileEmail = savedProfile.Email;
            profileAvatarUrl = savedProfile.AvatarUrl;
            profileBio = savedProfile.Bio;
        }
        ShowToast("Changes discarded.", "info");
    }

    // Notification actions
    private void ToggleMuteChannel(string channel, bool isMuted)
    {
        if (isMuted && !mutedChannels.Contains(channel))
            mutedChannels.Add(channel);
        else if (!isMuted)
            mutedChannels.Remove(channel);
    }

    private async Task SaveNotifications()
    {
        var prefs = new NotificationPrefs(notifEmail, notifPush, notifWeeklyDigest, mutedChannels);
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        ShowToast("Notification preferences saved!", "success");
    }

    // Security actions
    private void TogglePasswordPanel() => showPasswordPanel = !showPasswordPanel;

    private async Task UpdatePassword()
    {
        if (string.IsNullOrWhiteSpace(newPassword) || string.IsNullOrWhiteSpace(currentPassword))
        {
            ShowToast("Please fill in all password fields.", "error");
            return;
        }

        if (newPassword != confirmPassword)
        {
            ShowToast("New password and confirmation do not match.", "error");
            return;
        }

        try
        {
            await SettingsService.ChangePasswordAsync(currentPassword, newPassword);
            currentPassword = "";
            newPassword = "";
            confirmPassword = "";
            showPasswordPanel = false;
            ShowToast("Password updated successfully!", "success");
        }
        catch (Exception ex)
        {
            ShowToast($"Error updating password: {ex.Message}", "error");
        }
    }

    private void ConfirmRevokeSession(string sessionId)
    {
        sessionToRevoke = sessionId;
        showRevokeConfirmation = true;
    }

    private void CancelRevoke()
    {
        showRevokeConfirmation = false;
        sessionToRevoke = null;
    }

    private async Task RevokeSession()
    {
        if (sessionToRevoke != null)
        {
            await SettingsService.RevokeSessionAsync(sessionToRevoke);
            activeSessions?.RemoveAll(s => s.Id == sessionToRevoke);
            ShowToast("Session revoked.", "success");
        }
        showRevokeConfirmation = false;
        sessionToRevoke = null;
    }

    // Appearance actions
    private string GetPreviewStyle()
    {
        var bg = appearanceTheme == "Dark" ? "#1e1e2e; color: #cdd6f4" : "#ffffff; color: #1e1e2e";
        var fontSize = appearanceFontSize switch
        {
            "Small" => "12px",
            "Large" => "18px",
            _ => "14px"
        };
        var padding = appearanceCompactMode ? "8px" : "16px";
        return $"background: {bg}; font-size: {fontSize}; padding: {padding}; border-radius: 8px; border: 1px solid #ccc; margin-top: 1rem;";
    }

    private async Task SaveAppearance()
    {
        var settings = new AppearanceSettings(appearanceTheme, appearanceFontSize, appearanceLanguage, appearanceCompactMode);
        await SettingsService.SaveAppearanceAsync(settings);
        ShowToast("Appearance settings saved!", "success");
    }

    // Toast helpers
    private void ShowToast(string message, string type)
    {
        toastMessage = message;
        toastType = type;
        _ = DismissToastAfterDelay();
    }

    private async Task DismissToastAfterDelay()
    {
        await Task.Delay(3000);
        toastMessage = null;
        await InvokeAsync(StateHasChanged);
    }

    private void DismissToast() => toastMessage = null;
}
